function demoMain(idx,label){
  var objs=[{a:1,b:"x"},{a:2,b:"yy",c:[1,2]},{a:3}];
  var o=objs[idx%objs.length];
  var bytes=JSON.stringify(o).length;
  return "["+label+"] serialized "+JSON.stringify(o)+" -> "+bytes+" bytes, roundtrip="+(JSON.stringify(JSON.parse(JSON.stringify(o)))===JSON.stringify(o)?"OK":"FAIL");
}

